const identifyTaskDB=[{"s":"Las tres pruebas con que se persuade: el carácter, la emoción y el argumento.","type":"Ethos, pathos y logos (Aristóteles, hacia el 335 a.C.)"},{"s":"Cuando a alguien le quitan su libertad de elegir, se resiste y a veces hace lo contrario.","type":"La reactancia psicológica (Brehm, 1966)"},{"s":"El mecanismo medido por el que un relato absorbe al lector y baja su contraargumento.","type":"El transporte narrativo (Green y Brock, 2000)"},{"s":"El modelo que explica por qué el absorbido no elabora contraargumentos.","type":"El E-ELM (Slater y Rouner, 2002)"},{"s":"Somos «homo narrans»: razonamos con historias.","type":"El paradigma narrativo (Fisher, 1984)"},{"s":"Influir es legítimo cuando respeta la capacidad de reflexionar del otro.","type":"El freno ético (Sunstein, 2016)"},{"s":"Tratar a las personas como fines, nunca solo como medios.","type":"La raíz kantiana (Kant, 1785)"},{"s":"Las narrativas influyen en creencias y actitudes, con un efecto moderado.","type":"El metaanálisis de Braddock y Dillard (2016)"},{"s":"Herramienta de esta etapa con tres casillas: ¿abre o sustituye?, ¿respeta?, ¿aguanta el mecanismo?","type":"El freno ético del relato"},{"s":"Una historia persuasiva que no encaja con lo que el público ya sabe.","type":"La fidelidad narrativa fallida (Fisher, 1984)"}];
const classifyTaskDB=[{"w":"Ethos, pathos y logos","gen":"Tratado clásico","n":"Las tres pruebas de la persuasión","g":"Retórica clásica","t":"Aristóteles, hacia el 335 a.C."},{"w":"La reactancia psicológica","gen":"Teoría con apoyo experimental","n":"Resistencia a que empujen una creencia","g":"Psicología social","t":"Brehm, 1966"},{"w":"El transporte narrativo","gen":"Hallazgo experimental","n":"Absorción del lector, baja el contraargumento","g":"Psicología de la persuasión","t":"Green y Brock, 2000"},{"w":"El E-ELM","gen":"Modelo teórico","n":"Por qué el relato esquiva las defensas","g":"Comunicación","t":"Slater y Rouner, 2002"},{"w":"El paradigma narrativo","gen":"Marco teórico de autor","n":"Homo narrans: razonamos con historias","g":"Teoría de la comunicación","t":"Fisher, 1984"},{"w":"El freno ético","gen":"Marco ético","n":"La línea entre influir y manipular","g":"Filosofía política","t":"Sunstein, 2016"},{"w":"La raíz kantiana","gen":"Filosofía moral clásica","n":"Personas como fines, no medios","g":"Ética","t":"Kant, 1785"},{"w":"El metaanálisis narrativo","gen":"Metaanálisis","n":"Efecto real pero modesto de las narrativas","g":"Psicología de la persuasión","t":"Braddock y Dillard, 2016"},{"w":"La fidelidad narrativa","gen":"Prueba teórica de autor","n":"Si la historia encaja con lo que se sabe","g":"Teoría de la comunicación","t":"Fisher, 1984"},{"w":"El freno ético del relato","gen":"Herramienta práctica","n":"Abre o sustituye, respeta, aguanta el mecanismo","g":"Herramienta de esta casa","t":"Etapa 9"}];
const completeTaskDB=[{"s":"Aristóteles llama a las tres pruebas ethos, pathos y ___.","opts":["logos","mythos","kairos"],"ans":"logos"},{"s":"Brehm describe la reactancia ___.","opts":["psicológica","musical","técnica"],"ans":"psicológica"},{"s":"Green y Brock miden el transporte ___.","opts":["narrativo","visual","técnico"],"ans":"narrativo"},{"s":"Slater y Rouner llaman a su modelo el E-___.","opts":["ELM","LOG","ARG"],"ans":"ELM"},{"s":"Fisher llama al ser humano homo ___.","opts":["narrans","sapiens","faber"],"ans":"narrans"},{"s":"Sunstein escribe sobre la ética de la ___.","opts":["influencia","gramática","imprenta"],"ans":"influencia"},{"s":"Kant pide tratar a las personas como ___, no como medios.","opts":["fines","números","clientes"],"ans":"fines"},{"s":"El freno ético del relato tiene tres ___.","opts":["casillas","escenas","autores"],"ans":"casillas"}];
const explainQuestions=[{"q":"Explica las tres pruebas de la persuasión, según Aristóteles, «Retórica» (hacia el 335 a.C.), y por qué la retórica es un arte neutral.","ans":"Aristóteles, en su «Retórica» (hacia el 335 a.C.), describe tres pruebas con las que se persuade: el ethos, el carácter de quien habla; el pathos, la emoción que despierta; y el logos, el argumento que ofrece. Y avisa, en el mismo tratado, que la retórica es un arte NEUTRAL: la técnica sirve tanto para defender lo justo como para defender lo injusto, según quién la use. Por eso esta etapa no busca eliminar la retórica, sino ponerle un freno ético por fuera de la técnica: el arte de persuadir no trae su propia brújula moral incorporada."},{"q":"Explica la reactancia psicológica, según Jack Brehm, «A Theory of Psychological Reactance» (1966), y su límite.","ans":"Jack Brehm, en 1966, describe la reactancia psicológica: cuando alguien siente que le están empujando una creencia y le quitan su libertad de elegir, se resiste, y a veces hace justo lo contrario de lo que se le pedía, el llamado efecto boomerang. Es el límite natural de la persuasión: pasarse de fuerza puede volverse en contra de quien persuade. Su límite es que es una teoría con apoyo experimental, pero la fuerza del efecto varía según el caso y la persona."},{"q":"Explica el transporte narrativo, según Melanie Green y Timothy Brock (2000), y su límite.","ans":"Melanie Green y Timothy Brock, en «The role of transportation in the persuasiveness of public narratives» (2000), describen el transporte narrativo: el mecanismo medido por el que un relato absorbe al lector y, mientras está transportado, no discute lo que se le cuenta como discutiría una afirmación directa. Es el motor de la persuasión narrativa. Su límite es central para esta etapa: el transporte mide la absorción, pero por sí solo NO distingue si lo que persuade es verdad, solo dice cuánto baja el contraargumento."},{"q":"Explica el E-ELM, según Michael Slater y Donna Rouner, «Entertainment-education and elaboration likelihood» (2002), y por qué explica que la historia esquiva las defensas.","ans":"Michael Slater y Donna Rouner, en 2002, proponen el E-ELM: el modelo que explica que un relato persuade PORQUE la persona absorbida no elabora contraargumentos, al revés de lo que ocurriría frente a un mensaje persuasivo directo, que sí los activa. Es la explicación de por qué la historia esquiva las defensas críticas que un anuncio o un discurso directo tendrían que atravesar. Su límite es que es un modelo teórico con apoyo empírico, no una ley: el efecto depende del grado de transporte que logre cada historia concreta."},{"q":"Explica el freno ético del relato, la herramienta de esta etapa, y la raíz kantiana que cita.","ans":"El freno ético del relato es la herramienta de esta etapa, con tres casillas: ¿abre al dato o lo sustituye?, ¿respeta la autonomía del que escucha?, y ¿aguanta que se vea el mecanismo? Se apoya en Cass Sunstein, «The Ethics of Influence» (2016): influir es legítimo cuando respeta la capacidad del otro de reflexionar y no esconde su funcionamiento; es manipulación cuando esa capacidad se explota o se esquiva. Y cita, como raíz más vieja, a Immanuel Kant, «Fundamentación de la metafísica de las costumbres» (1785): tratar a las personas como fines, nunca solo como medios; manipular a alguien es usarlo como un mero medio."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> Cuando a alguien le quitan su libertad de elegir, se resiste. → <span style="color:var(--jade);font-weight:700;">La reactancia psicológica (Brehm, 1966)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

