const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda herramienta se cite con autor y año.","a":true},{"q":"Aristóteles publicó su «Retórica» hacia el 335 a.C.","a":true},{"q":"La retórica y la manipulación son exactamente la misma cosa.","a":false},{"q":"Aristóteles describe la retórica como un arte neutral, que sirve para lo justo y lo injusto.","a":true},{"q":"El transporte narrativo, por sí solo, distingue si lo que persuade es verdad.","a":false},{"q":"Jack Brehm publicó su teoría de la reactancia psicológica en 1966.","a":true},{"q":"Según Brehm, empujar de más una creencia nunca provoca resistencia.","a":false},{"q":"Melanie Green y Timothy Brock publicaron su estudio del transporte narrativo en 2000.","a":true},{"q":"Slater y Rouner proponen el E-ELM en 2002.","a":true},{"q":"Según Fisher (1984), el ser humano razona sobre todo con lógica formal, no con historias.","a":false},{"q":"Según Sunstein (2016), influir es legítimo cuando respeta la capacidad del otro de reflexionar.","a":true},{"q":"Kant, en 1785, pide tratar a las personas como fines, nunca solo como medios.","a":true},{"q":"El metaanálisis de Braddock y Dillard (2016) muestra que las narrativas nunca influyen en nada.","a":false},{"q":"El freno ético del relato tiene tres casillas: si abre o sustituye el dato, si respeta la autonomía, y si aguanta el mecanismo.","a":true},{"q":"Una historia manipuladora sustituye el dato en vez de abrirle camino.","a":true}];
const evalMCBank=[{"q":"Según Aristóteles, «Retórica» (hacia el 335 a.C.), ¿cuáles son las tres pruebas de la persuasión?","o":["a) Gancho, giro y cierre","b) Tesis, antítesis y síntesis","c) Causa, hueco y brecha","d) Ethos, pathos y logos"],"a":3},{"q":"¿Qué avisaba el propio Aristóteles sobre la retórica?","o":["a) Que solo sirve para mentir","b) Que es exclusiva de los tribunales","c) Que es un arte neutral, sirve para lo justo y para lo injusto","d) Que nunca debe enseñarse"],"a":2},{"q":"Según Jack Brehm (1966), ¿qué es la reactancia psicológica?","o":["a) Cuando alguien olvida un mensaje","b) Cuando alguien se emociona con una historia","c) Cuando un anuncio se repite muchas veces","d) Cuando a alguien le quitan su libertad de elegir, y se resiste, a veces al revés"],"a":3},{"q":"Según Green y Brock (2000), ¿qué hace el transporte narrativo?","o":["a) Mide el presupuesto de una historia","b) Mide cuántas veces se comparte un video","c) Absorbe al lector y baja su contraargumento","d) Mide la duración exacta de un relato"],"a":2},{"q":"Según Slater y Rouner (2002), el E-ELM explica que la historia persuade porque...","o":["a) siempre es más corta que un argumento directo","b) usa más colores en pantalla","c) el absorbido no elabora contraargumentos, al revés que un mensaje directo","d) se repite más veces que un anuncio"],"a":2},{"q":"Según Fisher (1984), ¿qué es el paradigma narrativo?","o":["a) Que las historias son irracionales","b) Que el ser humano razona con historias (homo narrans)","c) Que solo los abogados usan narrativas","d) Que la lógica reemplaza a las historias"],"a":1},{"q":"Según Fisher, ¿qué prueba la fidelidad narrativa de una historia?","o":["a) Que sea la más larga","b) Que suene verdadera y encaje con lo que se sabe","c) Que tenga más personajes","d) Que use más adjetivos"],"a":1},{"q":"Según Sunstein (2016), ¿cuándo es manipulación influir sobre alguien?","o":["a) Cuando se le cuenta una historia","b) Cuando se explota o se esquiva su capacidad de reflexionar","c) Cuando se usan datos comprobables","d) Cuando se declara la intención de persuadir"],"a":1},{"q":"Según Kant (1785), ¿cómo hay que tratar a las personas?","o":["a) Como fines, nunca solo como medios","b) Como medios para un fin","c) Como números en una encuesta","d) Como clientes, sin más"],"a":0},{"q":"¿Cuáles son las tres casillas del freno ético del relato?","o":["a) Título, música y duración","b) ¿Abre al dato o lo sustituye?, ¿respeta la autonomía?, ¿aguanta el mecanismo?","c) Presupuesto, elenco y locación","d) Gancho, giro y cierre"],"a":1},{"q":"Según el metaanálisis de Braddock y Dillard (2016), ¿cómo es el efecto de las narrativas?","o":["a) Real, pero con tamaños de efecto moderados","b) Arrollador y garantizado","c) Inexistente","d) Solo funciona con niños"],"a":0},{"q":"¿Cuál es la diferencia entre persuadir con honradez y manipular?","o":["a) Persuadir con honradez abre al dato; manipular lo sustituye","b) No hay ninguna diferencia real","c) Manipular siempre usa más datos","d) Persuadir con honradez nunca convence"],"a":0},{"q":"¿A qué se dedicó Edward Bernays, y cómo se conoce su trabajo?","o":["a) A medir la reactancia psicológica","b) A escribir la Retórica clásica","c) A formular el paradigma narrativo","d) A la ingeniería del consentimiento, industrializando la persuasión de masas"],"a":3},{"q":"¿A qué ruta abre la puerta esta etapa, la novena de la Ruta del Hilo que Tira?","o":["a) A la Ruta del Anzuelo Honrado","b) A la Ruta del Expediente Real","c) A la Ruta de Personas de Papel","d) A la Ruta del Mundo que Aguanta"],"a":0},{"q":"¿Cuál es la trampa que esta etapa desarma?","o":["a) «Nunca hay que persuadir a nadie»","b) «La retórica no sirve para nada»","c) «Si funciona, está bien», el fin justifica los medios","d) «Solo los datos convencen, nunca las historias»"],"a":2}];
