function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"LA CONVOCATORIA QUE ESCONDE EL DESTINO DEL DINERO. Una convocatoria de becas de L 150,000 cuenta la historia de un alumno que por fin puede estudiar, y solo hasta el anexo, en letra pequeña, explica en qué se gasta cada lempira."},{"txt":"EL VIDEO QUE AGUANTA LA TABLA COMPLETA. Un video de un proyecto de huertos de L 210,000 cuenta la historia real de una familia, y cierra mostrando la tabla completa de gastos, sin esconder nada."},{"txt":"EL MENSAJE QUE EMPUJA DE MÁS Y REBOTA. Un mensaje de una campaña de donación de L 95,000 dice «dona AHORA o la culpa es tuya», y varias personas dejan de donar, molestas."},{"txt":"LA HISTORIA DE MARCA QUE SUENA DEMASIADO PERFECTA. Una historia institucional de M.E.T.A.S de L 70,000 describe un giro tan perfecto que nadie en la sala termina de creerla."},{"txt":"LA CAMPAÑA QUE USA EL TRANSPORTE PARA QUE NADIE PREGUNTE. Una campaña de L 320,000 usa una historia tan absorbente que, en meses, nadie pregunta por los resultados del proyecto."},{"txt":"EL RELATO QUE DECLARA SU INTENCIÓN Y AUN ASÍ CONVENCE. Un video de L 140,000 empieza diciendo «te cuento esto para pedirte ayuda», y aun así convence a la mitad de quienes lo ven."},{"txt":"LA PRUEBA DEL MECANISMO, CON DOS HISTORIAS. Dos historias de una feria de M.E.T.A.S, cada una de L 55,000: una se cae si se explica cómo está armada; la otra aguanta."},{"txt":"EL TRATO CON UNA INSTITUCIÓN. Una reunión con una institución que financiaría L 400,000 pide una historia persuasiva, y alguien propone exagerar un dato para que decidan más rápido."}];
const critCaseQuestions=["1. Di si el problema de este caso está en que la historia SUSTITUYE el dato, NO RESPETA la autonomía, o NO AGUANTA el mecanismo, y por qué.","2. Aplica el freno ético completo: ¿abre al dato o lo sustituye?, ¿respeta la autonomía del que escucha?, ¿aguanta que se vea el mecanismo?","3. Aplica una herramienta de la etapa (Aristóteles hacia el 335 a.C., Brehm 1966, Green y Brock 2000, Slater y Rouner 2002, Fisher 1984, o Sunstein 2016) con su autor y su año.","4. Escribe la pregunta que decide y la condición con la que el caso quedaría resuelto."];
const critCaseGuides=["Se valora que se identifique con claridad de cuál de las tres casillas viene el problema real del caso, sin mezclar las tres en una sola respuesta vaga.","Se valora que las tres casillas queden llenas con algo concreto del caso, o con la nota honesta de que alguna todavía no se puede llenar.","Se valora que la herramienta elegida encaje con el problema real del caso (un dato escondido pide a Sunstein y al freno de la casa; un mensaje que empuja de más pide a Brehm; una historia que no encaja con lo sabido pide a Fisher) y que viaje con su autor y su año.","Se valora que la pregunta que decide sea concreta y que la condición diga con claridad qué cambiaría para que el caso quedara resuelto. No se valora cerrar con «si funciona, está bien», que es justo la trampa que este caso desmiente."];
const critErrorBank=[{"txt":"«Si el video convenció, ya está bien hecho, no hace falta revisar nada más»","g1":"Confunde eficacia con honradez: convencer no prueba que la historia abra al dato (el freno ético del relato).","g2":"No distingue persuadir con honradez de manipular; una historia puede convencer y sustituir el dato a la vez."},{"txt":"«La retórica es peligrosa, hay que evitarla siempre en la casa»","g1":"Trata como vicio lo que Aristóteles (hacia el 335 a.C.) describe como un arte neutral: sirve para lo justo y para lo injusto, según quién la use.","g2":"No distingue la técnica (neutral) del freno ético que hay que ponerle por fuera."},{"txt":"«Si el mensaje no convence, hay que insistir con más fuerza»","g1":"Ignora la reactancia (Brehm, 1966): empujar de más puede producir el efecto boomerang.","g2":"No busca si el mensaje ya está provocando resistencia en vez de acercar."},{"txt":"«El transporte narrativo prueba que la historia es honesta, porque la gente se emocionó»","g1":"Confunde absorción con honestidad: Green y Brock (2000) miden cuánto absorbe un relato, no si lo que persuade es verdad.","g2":"No aplica la fidelidad narrativa (Fisher, 1984): si la historia encaja con lo que el público ya sabe."},{"txt":"«Declarar que se quiere pedir dinero le quita fuerza a la historia»","g1":"Invierte el freno ético: declarar la intención de persuadir no le resta fuerza a una historia honrada, es la prueba de que aguanta el mecanismo (Sunstein, 2016).","g2":"No distingue esconder la intención (manipular) de declararla y aun así convencer (persuadir con honradez)."},{"txt":"«Exagerar un dato ayuda a que la institución decida más rápido»","g1":"Usa a quien decide como un mero medio para un fin, en contra de la raíz kantiana (Kant, 1785).","g2":"No aplica la primera casilla del freno: la historia SUSTITUYE el dato real por uno exagerado, en vez de abrirle camino."}];
const critDecisionBank=["La convocatoria de becas de L 150,000 ya cuenta la historia del alumno, y el destino del dinero sigue en el anexo: ¿se mueve el dato a la pantalla principal, se deja en el anexo porque «ya está», o se quita la historia por completo? Di qué harías.","El video de huertos de L 210,000 ya muestra la historia y la tabla de gastos completa: ¿se deja como está, se le añade más música para «reforzar» la persuasión, o se recorta la tabla porque «ya convenció bastante»? Di el efecto de cada opción.","El mensaje de donación de L 95,000 ya dice «dona AHORA o la culpa es tuya», y varias personas dejaron de donar: ¿se sube el tono todavía más, se retira el mensaje y se cambia por una invitación con datos, o se deja igual porque «algunos sí donaron»? Di qué harías.","La historia institucional de L 70,000 ya suena demasiado perfecta para que le crean: ¿se ajusta el relato a lo verosímil, aunque sea menos impactante, se deja igual porque «así impresiona más», o se le añaden más detalles perfectos todavía? Di qué se pierde con cada opción.","La campaña de L 320,000 ya lleva meses sin que nadie pregunte por los resultados: ¿se publica el informe de resultados junto con la historia, se deja la historia sola porque «ya está funcionando», o se hace una historia todavía más absorbente? Di la condición con la que sí lo dejarías.","El video de L 140,000 ya declara «te cuento esto para pedirte ayuda», y convence a la mitad de quienes lo ven: ¿se quita la declaración para «no parecer que se está pidiendo», se mantiene como está, o se agrega antes un aviso legal largo? Di qué harías.","De las dos historias de la feria de L 55,000, una se cae si se explica cómo está armada y la otra aguanta: ¿se elige la que aguanta para repetirla, se combinan las dos, o se elige la que más convenció en el momento, sin comprobar si aguanta? Di con qué protocolo lo decidirías.","En la reunión con la institución que financiaría L 400,000, alguien propone exagerar un dato para que decidan más rápido: ¿se exagera el dato, se cuenta la historia real aunque tarde más en convencer, o se exagera solo «un poco»? Di el riesgo de cada opción."];
const critDecisionGuide="La decisión se puntúa por el procedimiento con que se llegó a ella, no por lo audaz que suene. Se valora que se identifique si el problema real está en que la historia sustituye el dato, no respeta la autonomía, o no aguanta el mecanismo, y que la herramienta elegida (Aristóteles, Brehm, Green y Brock, Slater y Rouner, Fisher, o Sunstein) encaje con el problema real y viaje con su autor y su año. Se valora que la respuesta no se cierre con «si funciona, está bien», que es la trampa que esta etapa sustituye. Se valora la honradez cuando el caso, tal como está descrito, no permite decidir con los datos que hay: decir «falta este dato» es una respuesta correcta.";
const critCompareBank=[{"a":"«La convocatoria cuenta la historia del alumno, y el destino del dinero queda en un anexo, en letra pequeña.»","b":"«La convocatoria cuenta la misma historia, y en la siguiente pantalla muestra, con toda claridad, en qué se gasta cada lempira.»","ga":"Sustituye el dato: no aguanta el freno ético, y por eso es un caso de manipulación.","gb":"Abre al dato: la historia arriba, la cifra completa debajo, a la vista, sin esconderla.","gr":"Las dos convocatorias cuentan la misma historia. La diferencia es si el dato se enseña o se esconde, que es justo la línea entre persuadir y manipular."},{"a":"«El mensaje de donación dice: dona AHORA o la culpa es tuya.»","b":"«El mensaje de donación cuenta la misma necesidad, e invita a donar con la cifra exacta de lo que hace falta.»","ga":"Empuja tanto que provoca reactancia (Brehm, 1966): el efecto boomerang, la gente se resiste.","gb":"Persuade con honradez: respeta la libertad de decidir, sin empujar con culpa.","gr":"Los dos mensajes piden lo mismo. La diferencia es si respetan la autonomía del que decide, o si la esquivan con presión."},{"a":"«La campaña usa una historia tan absorbente que nadie pregunta por los resultados en meses.»","b":"«La campaña usa una historia igual de absorbente, y publica el informe de resultados junto con ella.»","ga":"Usa el transporte narrativo (Green y Brock, 2000) para que el dato no se examine.","gb":"Usa el transporte narrativo sin esconder nada: la historia y el dato conviven.","gr":"Las dos campañas usan la misma historia absorbente. La diferencia es si el transporte se usa para abrir camino al dato, o para taparlo."},{"a":"«La historia institucional suena tan perfecta que nadie en la sala termina de creerla.»","b":"«La historia institucional cuenta el mismo caso, con sus partes imperfectas, y por eso el público le cree.»","ga":"Falla la fidelidad narrativa (Fisher, 1984): no encaja con lo que el público ya sabe que pasa de verdad.","gb":"Cumple la fidelidad narrativa: suena verdadera porque encaja con la experiencia del público.","gr":"Las dos cuentan el mismo caso. La diferencia es si la historia es tan perfecta que deja de sonar verdadera."}];
const critCauseBank=[{"cause":"Una convocatoria cuenta la historia de un alumno y esconde el destino del dinero en un anexo.","guide":"Es un caso de manipulación: no aguanta el freno ético. Se corrige moviendo el dato a la pantalla principal, junto a la historia (Sunstein, 2016)."},{"cause":"Un mensaje de donación dice «dona AHORA o la culpa es tuya».","guide":"Provoca reactancia (Brehm, 1966): empuja tanto que produce el efecto contrario. Se corrige cambiando la amenaza por una invitación con datos."},{"cause":"Una historia institucional describe un giro tan perfecto que nadie la cree.","guide":"Falla la fidelidad narrativa (Fisher, 1984): no encaja con lo que el público sabe. Se corrige ajustando el relato a lo verosímil."},{"cause":"Una campaña usa una historia muy absorbente durante meses, sin publicar resultados.","guide":"Usa el transporte narrativo (Green y Brock, 2000) para que nadie examine el dato. Se corrige publicando el informe junto con la historia."},{"cause":"Un video declara desde el inicio que busca pedir ayuda.","guide":"Es persuasión honrada: declarar la intención no resta fuerza, prueba que la historia aguanta el mecanismo (Sunstein, 2016)."},{"cause":"En una reunión con una institución, alguien propone exagerar un dato para decidir más rápido.","guide":"Usa a quien decide como un medio, contra la raíz kantiana (Kant, 1785). Se corrige contando el dato real, aunque tarde más en convencer."}];
const critEffectBank=[{"effect":"La convocatoria muestra el destino del dinero en la misma pantalla donde cuenta la historia del alumno.","guide":"Se aplicó el freno ético: la historia y el dato conviven, y deja de ser manipulación para ser una historia que aguanta el dato."},{"effect":"El mensaje de donación reemplaza la amenaza por una invitación con la cifra exacta.","guide":"Se pasó de empujar (con riesgo de reactancia, Brehm 1966) a persuadir con honradez, respetando la libertad de decidir."},{"effect":"La historia institucional se reescribe con sus partes imperfectas, tal como pasaron.","guide":"Se recuperó la fidelidad narrativa (Fisher, 1984): al encajar con lo que el público sabe, vuelve a sonar verdadera."},{"effect":"La campaña publica el informe de resultados junto con la historia absorbente.","guide":"Se usó el transporte narrativo (Green y Brock, 2000) para abrir camino al dato, no para taparlo."},{"effect":"El video mantiene la declaración «te cuento esto para pedirte ayuda», y convence igual.","guide":"Se comprobó que declarar la intención no le resta fuerza a una historia honrada: aguanta el mecanismo (Sunstein, 2016)."},{"effect":"En la reunión, se cuenta el dato real a la institución, aunque tarde más en convencer.","guide":"Se eligió tratar a quien decide como un fin, no como un medio (Kant, 1785), y persuadir con honradez en vez de manipular."}];
function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`⚖️ El freno ético del relato bajo presión · Forma ${cf} · La historia que persuade · Ruta del Hilo que Tira`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El caso sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">Aplica el freno ético del relato a este caso: ¿abre al dato o lo sustituye?, ¿respeta la autonomía del que escucha?, ¿aguanta que se vea el mecanismo?, y qué herramienta (con su autor y su año) usarías.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>⚖️ Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El freno ético bajo presión: '+total+'/100');}
  else showToast('⚖️ Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El caso sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">Aplica el freno ético del relato a este caso: ¿abre al dato o lo sustituye?, ¿respeta la autonomía del que escucha?, ¿aguanta que se vea el mecanismo?, y qué herramienta (con su autor y su año) usarías.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. El caso</div>`+critCaseQuestions.map((q,i)=>`<div class="p-crit-line">${q} ${critCaseGuides[i]}</div>`).join('')+`</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El freno ético del relato bajo presión · La historia que persuade · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #0e7490;background:#cffafe;color:#0e7490;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#0e7490;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #0e7490;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#cffafe;border-left:3px solid #0e7490;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#cffafe;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#cffafe;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#0e7490;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #0e7490;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El freno ético del relato bajo presión · La historia que persuade · Ruta del Hilo que Tira · Etapa 9</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El freno ético del relato bajo presión · La historia que persuade · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"hacia el 335 a.C.","icon":"🏛️","label":"Aristóteles y la Retórica","text":"Aristóteles escribe su «Retórica», y describe las tres pruebas con que se persuade: el carácter de quien habla (ethos), la emoción (pathos) y el argumento (logos). Avisa, en el mismo tratado, que la retórica es un arte NEUTRAL: sirve para lo justo y para lo injusto. <strong>Por qué importa aquí:</strong> es la fecha más vieja de la tabla madre, y la advertencia de Aristóteles es la razón exacta por la que esta etapa pone un freno ético por fuera de la técnica."},{"y":"1785","icon":"📜","label":"Kant y la raíz ética","text":"Immanuel Kant publica su «Fundamentación de la metafísica de las costumbres», donde pide tratar a las personas como fines, nunca solo como medios. <strong>Por qué importa aquí:</strong> es la raíz ética más vieja citada en el freno de esta etapa; manipular a alguien es usarlo como un mero medio."},{"y":"1966","icon":"🔄","label":"Brehm y la reactancia","text":"Jack Brehm publica «A Theory of Psychological Reactance»: cuando alguien siente que le empujan una creencia y le quitan su libertad de elegir, se resiste, y a veces hace lo contrario, el efecto boomerang. <strong>Por qué importa aquí:</strong> es el límite natural de la persuasión, la prueba de que empujar de más se vuelve en contra."},{"y":"1984","icon":"📖","label":"Fisher y el paradigma narrativo","text":"Walter Fisher publica «Narration as a human communication paradigm»: somos «homo narrans», razonamos con historias, y juzgamos una historia por su racionalidad narrativa, si es coherente y si tiene fidelidad. <strong>Por qué importa aquí:</strong> da la prueba de que una historia persuasiva que falla la fidelidad es manipulación."},{"y":"2000","icon":"🌊","label":"Green y Brock y el transporte narrativo","text":"Melanie Green y Timothy Brock publican «The role of transportation in the persuasiveness of public narratives», donde miden el transporte narrativo: cuánto absorbe un relato al lector, y cómo eso baja su contraargumento. <strong>Por qué importa aquí:</strong> es el motor medido de por qué la historia esquiva las defensas críticas."},{"y":"2002","icon":"🧠","label":"Slater y Rouner y el E-ELM","text":"Michael Slater y Donna Rouner publican «Entertainment-education and elaboration likelihood»: el modelo que explica que el relato persuade PORQUE el absorbido no elabora contraargumentos, al revés que un mensaje directo. <strong>Por qué importa aquí:</strong> completa, con un mecanismo, lo que Green y Brock habían medido."},{"y":"2016","icon":"⚖️","label":"Sunstein y el freno ético","text":"Cass Sunstein publica «The Ethics of Influence»: influir es legítimo cuando respeta la capacidad del otro de reflexionar y no esconde su funcionamiento; es manipulación cuando esa capacidad se explota o se esquiva. <strong>Por qué importa aquí:</strong> es la prueba moderna de la línea, y el mismo año en que Richard Braddock y James Price Dillard publican su metaanálisis: el efecto de las narrativas es real, pero modesto, no arrollador."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: «SI LA HISTORIA CONVENCE, YA ESTÁ BIEN HECHA» ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(seAplicaFreno){sfx(seAplicaFreno?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(seAplicaFreno){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">⚖️</span><span class="ms-text"><strong>Se aplicó el freno ético del relato:</strong> se comprobó que el dato completo quedaba a la vista, se declaró la intención de pedir ayuda, y se dejó la historia lista para que cualquiera pudiera comprobar cómo estaba armada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Quedó apuntada la razón del cambio:</strong> «si convence, no basta: tiene que abrir al dato», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📤</span><span class="ms-text"><strong>Se publicó tal cual:</strong> el mensaje se quedó empujando con una amenaza de culpa, y varias personas que lo vieron dejaron de donar, molestas, sin que nadie entendiera del todo por qué.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚖️</span><span class="ms-text"><strong>Confundir «convence» con «está bien hecho»</strong> es exactamente el error que esta etapa señala: lo que distingue persuadir de manipular no es si funciona, es si la historia abre al dato y aguanta que se vea cómo se armó.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = El transporte que baja el
// contraargumento, paradoja = La persuasión honrada, utilidad = El freno
// ético, ruina = La manipulación (la historia que tapa el dato).
const parteData={"esperado":{"nombre":"El transporte que baja el contraargumento","icon":"🌊","estructura":{"title":"Qué es","info":"• El mecanismo medido por el que un relato absorbe al lector y baja su contraargumento<br>• Descrito por <strong>Melanie Green y Timothy Brock (2000)</strong>, «The role of transportation in the persuasiveness of public narratives»<br>• Cuanto más transportado, menos discute lo que se le cuenta<br>• NO dice, por sí solo, si lo que persuade es verdad"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿el relato absorbe de verdad, o solo aprieta un botón?<br>• Se compara con si el contraargumento queda esquivado o de verdad respondido<br>• Se busca si la absorción se usa para abrir camino al dato, o para taparlo<br>• Se anota en la primera casilla del freno ético: ¿abre o sustituye?"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que el transporte, por sí solo, prueba que la historia es honesta<br>• En confundir «me absorbió» con «es verdad»<br>• En olvidar el año de Green y Brock (2000) al citar el hallazgo<br>• En usar el transporte para que nadie pregunte por los resultados"},"cuidados":{"title":"En esta casa","info":"• Toda historia de esta casa se pregunta primero si absorbe, y después si lo hace con honradez<br>• Se declara siempre «Green y Brock, 2000» al lado, no «así convence siempre»<br>• Se usa como primer paso, antes de aplicar el freno ético completo<br>• Y se recuerda que absorber no es lo mismo que respetar"}},"paradoja":{"nombre":"La persuasión honrada","icon":"🔓","estructura":{"title":"Qué es","info":"• Persuadir para que el dato se entienda y se pida, no para que se esconda<br>• Se opone a la manipulación, que sustituye el dato por el caso<br>• Aristóteles (hacia el 335 a.C.) ya avisaba que la retórica es neutral: la honradez no viene de la técnica, viene de cómo se usa<br>• Es la que se confunde con «si convence, ya está bien»"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿esta historia abre camino al dato, o lo sustituye?<br>• Se busca si respeta la autonomía del que escucha (Sunstein, 2016)<br>• Se comprueba si aguanta que se le enseñe cómo está armada<br>• Se anota en las tres casillas del freno ético del relato"},"enfermedades":{"title":"Dónde se cae","info":"• En pedir que se crea la historia antes de mostrar el dato completo<br>• En creer que toda historia que convence es automáticamente honrada<br>• En citar a Sunstein (2016) sin mencionar la raíz de Kant (1785)<br>• En confundir «me convenció» con «es honesta»"},"cuidados":{"title":"En esta casa","info":"• Toda historia de esta casa declara su intención de persuadir, sin esconderla<br>• Se declara «Sunstein, 2016» y, si hace falta la raíz, «Kant, 1785»<br>• Se usa como diagnóstico: si una historia no aguanta que se explique, algo falla<br>• Y se recuerda que una historia honrada no necesita esconder nada"}},"utilidad":{"nombre":"El freno ético","icon":"⚖️","estructura":{"title":"Qué es","info":"• La herramienta de esta etapa, en tres casillas: ¿abre al dato o lo sustituye?, ¿respeta la autonomía?, ¿aguanta el mecanismo?<br>• <strong>Cass Sunstein (2016)</strong>: influir respeta la reflexión; manipular la explota o la esquiva<br>• <strong>Immanuel Kant (1785)</strong>: la raíz, tratar a las personas como fines, no como medios<br>• Si no aguanta que se muestre el mecanismo, es manipulación"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿esta historia sale de algo comprobable?<br>• Se busca si respeta que el que escucha decida por su cuenta<br>• Se comprueba si la historia aguanta que se explique cómo se armó<br>• Se anota en las tres casillas, aunque a veces una quede pendiente"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que basta con una de las tres casillas llena<br>• En esconder el mecanismo que la propia historia debería aguantar<br>• En dejar una casilla sin llenar, y fingir que el freno cerró igual<br>• En olvidar que el transporte narrativo puede tapar el dato, no solo abrirle camino"},"cuidados":{"title":"En esta casa","info":"• Todo relato de la casa declara si abre al dato, respeta la autonomía y aguanta el mecanismo, a propósito<br>• Se declara «Sunstein, 2016» junto a la raíz de «Kant, 1785»<br>• Se usa como la prueba final antes de publicar cualquier historia persuasiva<br>• Y se recuerda que ninguna casilla se salta"}},"ruina":{"nombre":"La manipulación (la historia que tapa el dato)","icon":"🚫","estructura":{"title":"Qué es","info":"• Contar una historia para que el dato NO se examine, un atajo que esquiva el juicio<br>• Es lo que <strong>Sunstein (2016)</strong> llama explotar o esquivar la capacidad de reflexionar<br>• Usar a la persona como un mero medio, en contra de <strong>Kant (1785)</strong><br>• No es lo mismo que persuadir con honradez, aunque use las mismas técnicas"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿esta historia sustituye un dato que debería estar a la vista?<br>• Si el dato queda escondido o exagerado, es manipulación<br>• Se compara con la persuasión honrada: ¿la historia haría lo mismo con el dato completo a la vista?<br>• Se decide si la historia se cae, o aguanta, al enseñar su mecanismo"},"enfermedades":{"title":"Dónde se cae","info":"• En esconder el dato en un anexo, en letra pequeña<br>• En usar el transporte narrativo (Green y Brock, 2000) para que nadie pregunte<br>• En empujar tanto que provoca reactancia (Brehm, 1966)<br>• En olvidar que la manipulación es un fallo ético, no solo una técnica de más"},"cuidados":{"title":"En esta casa","info":"• Toda historia sospechosa, en esta casa, se revisa antes de usarse<br>• Se pregunta siempre: ¿qué dato estaría escondiendo esta historia?<br>• Se prefiere la historia honrada cuando el atajo no aporta nada que valga el riesgo<br>• Y se recuerda la raíz de Kant (1785): nadie se usa como un mero medio"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con la entrevista
// y la conversación la etiqueta crece: además del pastiche hay que declarar que
// el encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={"borges":{"titulo":"El hombre que convencía de cualquier cosa","tipo":"Cuento, a la manera de Jorge Luis Borges"},"cervantes":{"titulo":"El bálsamo que no necesitaba funcionar","tipo":"Capítulo, a la manera de Miguel de Cervantes Saavedra"},"harari":{"titulo":"La especie que se deja convencer por una buena historia","tipo":"Ensayo, a la manera de Yuval Noah Harari"},"entrevista":{"titulo":"La ingeniería del consentimiento, y su reverso","tipo":"Entrevista imaginada con Edward Bernays, a la manera de Joaquín Soler Serrano","ficcion":true},"gala":{"titulo":"Convencer no es vencer","tipo":"El Loco de la Colina: Jesús Quintero conversa con Miguel de Unamuno (conversación imaginada)","ficcion":true},"debate":{"titulo":"¿Persuadir con una historia es legítimo, o siempre es una forma de manipular?","tipo":"Careo: las dos posturas de una disputa abierta, con sus réplicas","careo":true}};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Las personas citadas se mencionan en tercera persona como fuentes, <strong>toda obra, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · La historia que persuade · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#78350f;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#0e7490;border-bottom:1.5pt solid #0e7490;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #0e7490;background:#cffafe;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#78350f;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#0e7490;background:#cffafe;border-left:3pt solid #0e7490;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#0e7490;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Storytelling</span><span>⚖️ La historia que persuade${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 9 de 12</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 9 de 12</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «La historia que persuade»</h1><div class="tipo">Un cuento, un capítulo, un ensayo, una entrevista imaginada, una conversación imaginada y un careo, sobre el mismo tema</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra, de Yuval Noah Harari, de Edward Bernays ni de Miguel de Unamuno</strong>, el sexto es un careo escrito por la casa sobre una disputa real, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. La entrevista con Edward Bernays y la conversación entre Jesús Quintero y Miguel de Unamuno son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 9 de 12</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">La historia que persuade · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes, Harari, Bernays ni Unamuno, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron). El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

